1	import { createReadStream, promises as fs } from "node:fs";
2	import path from "node:path";
3	import { createHash } from "node:crypto";
4	import { notFound } from "../errors.js";
5	import { resolvePaperclipInstanceRoot } from "../home-paths.js";
6	
7	export type WorkspaceOperationLogStoreType = "local_file";
8	
9	export interface WorkspaceOperationLogHandle {
10	  store: WorkspaceOperationLogStoreType;
11	  logRef: string;
12	}
13	
14	export interface WorkspaceOperationLogReadOptions {
15	  offset?: number;
16	  limitBytes?: number;
17	}
18	
19	export interface WorkspaceOperationLogReadResult {
20	  content: string;
21	  nextOffset?: number;
22	}
23	
24	export interface WorkspaceOperationLogFinalizeSummary {
25	  bytes: number;
26	  sha256?: string;
27	  compressed: boolean;
28	}
29	
30	export interface WorkspaceOperationLogStore {
31	  begin(input: { companyId: string; operationId: string }): Promise<WorkspaceOperationLogHandle>;
32	  append(
33	    handle: WorkspaceOperationLogHandle,
34	    event: { stream: "stdout" | "stderr" | "system"; chunk: string; ts: string },
35	  ): Promise<void>;
36	  finalize(handle: WorkspaceOperationLogHandle): Promise<WorkspaceOperationLogFinalizeSummary>;
37	  read(handle: WorkspaceOperationLogHandle, opts?: WorkspaceOperationLogReadOptions): Promise<WorkspaceOperationLogReadResult>;
38	}
39	
40	function safeSegments(...segments: string[]) {
41	  return segments.map((segment) => segment.replace(/[^a-zA-Z0-9._-]/g, "_"));
42	}
43	
44	function resolveWithin(basePath: string, relativePath: string) {
45	  const resolved = path.resolve(basePath, relativePath);
46	  const base = path.resolve(basePath) + path.sep;
47	  if (!resolved.startsWith(base) && resolved !== path.resolve(basePath)) {
48	    throw new Error("Invalid log path");
49	  }
50	  return resolved;
51	}
52	
53	function createLocalFileWorkspaceOperationLogStore(basePath: string): WorkspaceOperationLogStore {
54	  async function ensureDir(relativeDir: string) {
55	    const dir = resolveWithin(basePath, relativeDir);
56	    await fs.mkdir(dir, { recursive: true });
57	  }
58	
59	  async function readFileRange(filePath: string, offset: number, limitBytes: number): Promise<WorkspaceOperationLogReadResult> {
60	    const stat = await fs.stat(filePath).catch(() => null);
61	    if (!stat) throw notFound("Workspace operation log not found");
62	
63	    const start = Math.max(0, Math.min(offset, stat.size));
64	    const end = Math.max(start, Math.min(start + limitBytes - 1, stat.size - 1));
65	
66	    if (start > end) {
67	      return { content: "", nextOffset: start };
68	    }
69	
70	    const chunks: Buffer[] = [];
71	    await new Promise<void>((resolve, reject) => {
72	      const stream = createReadStream(filePath, { start, end });
73	      stream.on("data", (chunk) => {
74	        chunks.push(Buffer.isBuffer(chunk) ? chunk : Buffer.from(chunk));
75	      });
76	      stream.on("error", reject);
77	      stream.on("end", () => resolve());
78	    });
79	
80	    const content = Buffer.concat(chunks).toString("utf8");
81	    const nextOffset = end + 1 < stat.size ? end + 1 : undefined;
82	    return { content, nextOffset };
83	  }
84	
85	  async function sha256File(filePath: string): Promise<string> {
86	    return new Promise<string>((resolve, reject) => {
87	      const hash = createHash("sha256");
88	      const stream = createReadStream(filePath);
89	      stream.on("data", (chunk) => hash.update(chunk));
90	      stream.on("error", reject);
91	      stream.on("end", () => resolve(hash.digest("hex")));
92	    });
93	  }
94	
95	  return {
96	    async begin(input) {
97	      const [companyId] = safeSegments(input.companyId);
98	      const operationId = safeSegments(input.operationId)[0]!;
99	      const relDir = companyId;
100	      const relPath = path.join(relDir, `${operationId}.ndjson`);
101	      await ensureDir(relDir);
102	
103	      const absPath = resolveWithin(basePath, relPath);
104	      await fs.writeFile(absPath, "", "utf8");
105	
106	      return { store: "local_file", logRef: relPath };
107	    },
108	
109	    async append(handle, event) {
110	      if (handle.store !== "local_file") return;
111	      const absPath = resolveWithin(basePath, handle.logRef);
112	      const line = JSON.stringify({
113	        ts: event.ts,
114	        stream: event.stream,
115	        chunk: event.chunk,
116	      });
117	      await fs.appendFile(absPath, `${line}\n`, "utf8");
118	    },
119	
120	    async finalize(handle) {
121	      if (handle.store !== "local_file") {
122	        return { bytes: 0, compressed: false };
123	      }
124	      const absPath = resolveWithin(basePath, handle.logRef);
125	      const stat = await fs.stat(absPath).catch(() => null);
126	      if (!stat) throw notFound("Workspace operation log not found");
127	
128	      const hash = await sha256File(absPath);
129	      return {
130	        bytes: stat.size,
131	        sha256: hash,
132	        compressed: false,
133	      };
134	    },
135	
136	    async read(handle, opts) {
137	      if (handle.store !== "local_file") {
138	        throw notFound("Workspace operation log not found");
139	      }
140	      const absPath = resolveWithin(basePath, handle.logRef);
141	      const offset = opts?.offset ?? 0;
142	      const limitBytes = opts?.limitBytes ?? 256_000;
143	      return readFileRange(absPath, offset, limitBytes);
144	    },
145	  };
146	}
147	
148	let cachedStore: WorkspaceOperationLogStore | null = null;
149	
150	export function getWorkspaceOperationLogStore() {
151	  if (cachedStore) return cachedStore;
152	  const basePath = process.env.WORKSPACE_OPERATION_LOG_BASE_PATH
153	    ?? path.resolve(resolvePaperclipInstanceRoot(), "data", "workspace-operation-logs");
154	  cachedStore = createLocalFileWorkspaceOperationLogStore(basePath);
155	  return cachedStore;
156	}
